class BalancedBrackets:
    LEFT_BRACKETS = ["(", "{", "["]
    RIGHT_BRACKETS = [")", "}", "]"]
    LEFT_BRACKET_TO_RIGHT_BRACKET = {"(": ")", "{": "}", "[": "]"}

    def __init__(self, expr):
        self._stack = []
        self._left_brackets = self.LEFT_BRACKETS
        self._right_brackets = self.RIGHT_BRACKETS
        self._expr = expr

    @property
    def stack(self):
        return self._stack

    def clear_expr(self):
        self._expr = ''.join(c for c in self._expr if (c in self._left_brackets or c in self._right_brackets))

    def _is_left_bracket(self, char):
        return char in self._left_brackets

    def _validate_bracket_pair(self, left_bracket, right_bracket):
        return left_bracket != self.LEFT_BRACKET_TO_RIGHT_BRACKET.get(right_bracket)

    def check_balanced_brackets(self):
        self.clear_expr()
        for bracket in self._expr:
            if self._is_left_bracket(bracket):
                self._stack.append(bracket)
            else:
                if not self._stack:
                    return False
                current_bracket = self._stack.pop()
                if self._validate_bracket_pair(current_bracket, bracket):
                    return False
        return not self._stack
